import * as T from './vendor/three.module.js';
import {systems,presets} from './body-data.js';
export function geometryFromChunk(p,buffer){if(p.positions+p.vertexCount*12>buffer.byteLength||p.indices+p.indexCount*4>buffer.byteLength)throw Error('Invalid model buffer');const g=new T.BufferGeometry();g.setAttribute('position',new T.BufferAttribute(new Float32Array(buffer,p.positions,p.vertexCount*3),3));g.setAttribute('normal',new T.BufferAttribute(new Int16Array(buffer,p.normals,p.vertexCount*3),3,true));g.setIndex(new T.BufferAttribute(new Uint32Array(buffer,p.indices,p.indexCount),1));g.boundingBox=new T.Box3(new T.Vector3(...p.bounds[0]),new T.Vector3(...p.bounds[1]));g.computeBoundingSphere();return g}
export class BodyModel{
 constructor(meta,config={}){this.systems=config.systems||systems;this.presets=config.presets||presets;this.meta=meta;this.parts=meta.parts;this.root=new T.Group();this.batches=new Map();this.byId=new Map();this.loaded=new Map();this.enabled=new Set(this.presets.overview);this.hidden=new Set();this.selected=null;this.isolated=false;this.separation=0;this.opacity=Object.fromEntries(Object.keys(this.systems).map(k=>[k,k==='integumentary'?.16:1]));const bounds=new T.Box3();this.parts.forEach(p=>{this.byId.set(p.id,p);bounds.expandByPoint(new T.Vector3(...p.bounds[0]));bounds.expandByPoint(new T.Vector3(...p.bounds[1]));});this.center=bounds.getCenter(new T.Vector3());this.scale=3.4/bounds.getSize(new T.Vector3()).y;this.root.scale.setScalar(this.scale);this.root.position.copy(this.center).multiplyScalar(-this.scale);for(const system of Object.keys(this.systems)){const parts=this.parts.filter(p=>p.system===system);if(!parts.length)continue;const material=new T.MeshStandardMaterial({color:0xffffff,roughness:.7,metalness:0,side:T.DoubleSide});const batch=new T.BatchedMesh(parts.length,parts.reduce((n,p)=>n+p.vertexCount,0),parts.reduce((n,p)=>n+p.indexCount,0),material);batch.frustumCulled=false;batch.perObjectFrustumCulled=true;batch.userData.parts=[];this.batches.set(system,batch);this.root.add(batch)}}
 addChunk(ci,buffer){for(const p of this.parts.filter(p=>p.chunk===ci)){if(this.loaded.has(p.id))continue;const batch=this.batches.get(p.system),geometry=geometryFromChunk(p,buffer);const gi=batch.addGeometry(geometry),instance=batch.addInstance(gi);geometry.dispose();batch.userData.parts[instance]=p;const center=new T.Vector3(...p.bounds[0]).add(new T.Vector3(...p.bounds[1])).multiplyScalar(.5);this.loaded.set(p.id,{p,batch,instance,center,offset:new T.Vector3()});}this.update()}
 visible(p){return this.loaded.has(p.id)&&!this.hidden.has(p.id)&&this.enabled.has(p.system)&&(!this.isolated||p.id===this.selected)}
 update(){const matrix=new T.Matrix4();for(const [system,batch] of this.batches){batch.visible=this.enabled.has(system);const op=this.isolated?1:this.opacity[system];batch.material.opacity=op;batch.material.transparent=op<.99;batch.material.depthWrite=op>=.99;}
 for(const [id,item] of this.loaded){const {p,batch,instance,center,offset}=item;batch.setVisibleAt(instance,this.visible(p));const x=center.x-this.center.x,z=center.z-this.center.z;let dx=x,dz=z;if(Math.hypot(dx,dz)<.001){const angle=parseInt(id.replace(/\D/g,''),10)*2.39996;dx=Math.cos(angle)*.008;dz=Math.sin(angle)*.008}const length=Math.hypot(dx,dz);offset.set(dx/length*.19,(center.y-this.center.y)*.12,dz/length*.19).multiplyScalar(this.separation);matrix.makeTranslation(offset.x,offset.y,offset.z);batch.setMatrixAt(instance,matrix);batch.setColorAt(instance,new T.Color(id===this.selected?'#f4d477':this.systems[p.system].color));}this.root.updateMatrixWorld(true)}
 position(id){const p=this.byId.get(id);if(!p)return new T.Vector3();const v=new T.Vector3(...p.bounds[0]).add(new T.Vector3(...p.bounds[1])).multiplyScalar(.5);const entry=this.loaded.get(id);if(entry)v.add(entry.offset);return v.multiplyScalar(this.scale).add(this.root.position)}
 span(id){const p=this.byId.get(id);return new T.Vector3(...p.bounds[1]).sub(new T.Vector3(...p.bounds[0])).multiplyScalar(this.scale)}
 countVisible(){let n=0;for(const p of this.parts)if(this.visible(p))n++;return n}
 select(id){const p=this.byId.get(id);if(!p)return;this.selected=id;this.enabled.add(p.system);this.hidden.delete(id);this.update()}
 preset(key){this.enabled=new Set(this.presets[key]||this.presets.overview);this.isolated=false;this.hidden.clear();this.update()}
}
